# agent/branding.py - Marca de The Nail Society Spa (logo + animaciones estilo React Bits)
# Generado por AgentKit
"""Logo y efectos de marca de The Nail Society Spa para incrustar en las paginas (sin archivos externos).

Paleta de marca: blanco hueso de base, negro estructural, dorado para filos y
superficies de lujo, y naranja como acento que captura el clic. El dorado NO se
usa como color de texto (no alcanza contraste AA); va en auroras, halos y filetes."""

LOGO_DATA_URI = "data:image/jpeg;base64,"

ANIM_CSS = """/* === React Bits (vanilla) === */
.aurora{position:fixed;inset:0;z-index:0;pointer-events:none;overflow:hidden}
.aurora b{position:absolute;width:55vmax;height:55vmax;border-radius:50%;opacity:.55;will-change:transform}
.aurora b.a{background:radial-gradient(circle,rgba(201,162,77,.42),transparent 66%);top:-20vmax;right:-14vmax;animation:auroraA 18s ease-in-out infinite alternate}
.aurora b.b{background:radial-gradient(circle,rgba(232,120,44,.32),transparent 66%);bottom:-24vmax;left:-14vmax;animation:auroraB 23s ease-in-out infinite alternate}
@keyframes auroraA{to{transform:translate(-13vmax,11vmax) scale(1.2)}}
@keyframes auroraB{to{transform:translate(15vmax,-9vmax) scale(1.15)}}
header,main,.wrap,form.card{position:relative;z-index:1}
.marca h1,.head h1{background:linear-gradient(100deg,var(--tinta) 38%,#e8cf8f 50%,var(--tinta) 62%);background-size:220% 100%;-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;animation:shine 7s linear infinite}
@keyframes shine{to{background-position:-220% 0}}
.tarjeta,.stat,.opt,.card,.panel{position:relative}
.tarjeta::after,.stat::after,.opt::after,.card::after,.panel::after{content:"";position:absolute;inset:0;border-radius:inherit;background:radial-gradient(200px circle at var(--mx,50%) var(--my,50%),rgba(201,162,77,.15),transparent 62%);opacity:0;transition:opacity .25s;pointer-events:none}
.tarjeta:hover::after,.stat:hover::after,.opt:hover::after,.card:hover::after,.panel:hover::after{opacity:1}"""

# El JS de marca vive en static/marca.js (se carga como archivo externo, ver aplicar_marca).


def aplicar_marca(html: str) -> str:
    """Inyecta el logo y los efectos de marca en una pagina HTML.

    El CSS se mete inline (los estilos no ejecutan código). El JS, en cambio, se
    carga como archivo externo (/static/marca.js) para no usar scripts inline y
    permitir una CSP estricta en las paginas publicas.
    """
    html = html.replace("__LOGO__", LOGO_DATA_URI)
    html = html.replace("</head>", "<style>" + ANIM_CSS + "</style></head>", 1)
    html = html.replace("</body>", '<script src="/static/marca.js"></script></body>', 1)
    return html
